<template><el-dialog :model-value="modelValue" title="可视化装配" width="720" @close="$emit('update:modelValue',false)"><div class="wizard-body"><el-alert title="装配使用通用 fixed 连接，不依赖特定机器人名称" type="info" :closable="false"/><div class="assembly-grid"><label>父 Link<el-select v-model="parent"><el-option v-for="x in store.scene.links" :key="x.id" :label="x.name" :value="x.id"/></el-select></label><label>子模型<el-input v-model="childPath" placeholder="选择另一个模型文件"/><el-button @click="pickChild">浏览</el-button></label><label>子 Link<el-input v-model="childLink" placeholder="填写子模型根 Link"/></label><label>连接名称<el-input v-model="name"/></label></div><div class="transform-grid"><label v-for="(label,i) in ['X','Y','Z','R','P','Y']" :key="i">{{label}}<el-input-number v-model="transform[i]" :controls="false"/></label></div><div class="gizmo-placeholder">Transform Gizmo · 数值预览<br><small>装配写入工作区副本，不修改源模型</small></div></div><template #footer><el-button @click="$emit('update:modelValue',false)">关闭</el-button><el-button type="primary" :loading="store.busy" :disabled="!parent||!childPath||!childLink||!name" @click="assemble">创建 fixed 连接</el-button></template></el-dialog></template>
<script setup lang="ts">import {ref} from 'vue';import {ElMessage} from 'element-plus';import {pickPath} from '@/api/models';import {useEditorStore} from '@/stores/editor';defineProps<{modelValue:boolean}>();const emit=defineEmits(['update:modelValue']);const store=useEditorStore();const parent=ref('');const childPath=ref('');const childLink=ref('');const name=ref('assembly_joint');const transform=ref([0,0,0,0,0,0]);async function pickChild(){childPath.value=(await pickPath('file')).path}async function assemble(){try{await store.assemble({child_path:childPath.value,parent_link:parent.value,child_link:childLink.value,name:name.value,transform:transform.value});emit('update:modelValue',false);ElMessage.success('通用 fixed 装配已创建')}catch(error){ElMessage.error(String(error))}}</script>
